const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='xunji-v1';let db;try{db=JSON.parse(localStorage.getItem(key))}catch{}db={likes:[],favorites:[],comments:{},notes:[],checkins:[],visited:[],draft:null,following:false,...db};
const save=()=>{try{localStorage.setItem(key,JSON.stringify(db));return true}catch{toast('存储空间不足，请减少图片后重试');return false}},toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)};
const people=[{id:'su',name:'苏轼',dynasty:'宋',desc:'一蓑烟雨任平生。循着东坡的足迹，走进他的旷达人生。',img:1},{id:'li',name:'李白',dynasty:'唐',desc:'从长安到江南，在诗句中重访盛唐山河。',img:0},{id:'xin',name:'辛弃疾',dynasty:'宋',desc:'醉里挑灯看剑，读懂词人与时代的回响。',img:2}];
const places=[{id:'red',name:'黄州东坡赤壁',dynasty:'宋',desc:'苏轼在黄州留下《赤壁赋》等名篇。此处为文学纪念地，并非三国赤壁之战的确定发生地。',kind:'文学纪念地',img:2},{id:'lake',name:'杭州西湖 · 苏堤',dynasty:'宋',desc:'苏轼任杭州知州时组织疏浚西湖，筑成长堤。今天的景观经历历代维护与整治。',kind:'历史景观',img:1},{id:'tower',name:'西安大雁塔',dynasty:'唐',desc:'始建于唐代的佛教建筑，现存塔体经过历代修葺。',kind:'历史建筑',img:1}];
const seeds=[{id:'n1',title:'在黄州，读懂苏轼的「一蓑烟雨」',author:'山河故人',category:'人物考据',tags:'宋 · 苏轼 · 黄州',content:'元丰五年，苏轼在黄州。\n\n《定风波》小序记述了沙湖道中遇雨的经历。词中的风雨既是眼前之景，也为后世读者提供了理解其处境的入口。\n\n我们能从文本确认的是行旅遇雨；至于作者每一刻的心理，不宜以现代想象替代史料。沿着文字走近他，也为历史保留一点距离。',sources:'苏轼《定风波·莫听穿林打叶声》及小序',img:2},{id:'n2',title:'如果李白有一本旅行手帐',author:'青山客',category:'历史同人',tags:'唐 · 李白 · 创作',content:'【同人创作 · 以下情节为文学虚构】\n\n离开长安那日，我把月光收进行囊。酒壶很轻，山河很远。\n\n若有一日你也行至江畔，请替我看看，水中的月亮是否还同当年一样。',sources:'灵感来源：李白诗歌；本文并非史料',img:0},{id:'n3',title:'一条苏堤，半部杭州西湖史',author:'行走的书页',category:'遗址探访',tags:'宋 · 西湖 · 杭州',content:'从南向北走过苏堤，湖光在两侧展开。\n\n苏堤与苏轼治理西湖的历史相连，但今天所见桥梁、植被与步道，不能直接等同于北宋原貌。\n\n探访建议：先阅读地方志与园林介绍，再沿堤步行，记录你看见的历史层次。',sources:'《宋史》卷三三八·苏轼传；探访描述为演示内容',img:1}];
const notes=()=>[...db.notes,...seeds], findNote=id=>notes().find(n=>n.id===id),art=i=>`assets/art${i}.webp`,navs=[['home','⌂','发现'],['routes','♧','寻迹'],['community','▤','社区'],['ar','◎','AR'],['me','◯','我的']];let active='home',filter='全部',category='推荐',searchType='全部',stream=null,photo='',simulate=false,stamp='寻迹留念',editorImages=[],preview=false;
const go=(p,id='')=>{if(p==='search'&&id){db.recentSearches=[decodeURIComponent(id),...(db.recentSearches||[]).filter(x=>x!==decodeURIComponent(id))].slice(0,6);save()}location.hash=`/${p}${id?'/'+id:''}`},tag=t=>`<span class="tag ${t==='历史同人'?'fiction':'fact'}">${esc(t)}</span>`,button=(t,p,id='',cls='secondary')=>`<button class="${cls}" data-go="${p}" data-id="${id}">${t}</button>`;
function card(p,type){return `<article class="card"><button data-go="${type}" data-id="${p.id}"><div class="cover"><img src="${art(p.img)}" alt="历史建筑主题插画" loading="lazy"><span class="tag">${esc(p.dynasty||p.category)}</span></div><div class="body"><h3>${esc(p.name||p.title)}</h3><p>${esc(p.desc||p.tags)}</p><div class="meta"><span>${esc(p.kind||p.author||'人物档案')}</span><span>探索 →</span></div></div></button></article>`}
function noteCard(n){return card(n,'note')}
function shell(content,p){active=['person','event','place','search'].includes(p)?'home':['note','edit'].includes(p)?'community':p==='badges'?'me':p;$('#app').innerHTML=`${navigator.onLine?'':'<div class="offline">当前离线：仍可浏览本地内容，联网后可使用相机以外的外部能力。</div>'}<div class="shell"><aside class="sidebar"><div class="brand"><span class="seal">迹</span><div>寻迹历史<small>TRACES OF HISTORY</small></div></div><nav class="nav">${navs.map(([id,icon,t])=>`<button data-go="${id}" class="${active===id?'active':''}"><i>${icon}</i>${t}</button>`).join('')}</nav><footer>以史为引，循迹而行<br>iOS 风格响应式 Web 原型<br>数据仅保存在当前浏览器</footer></aside><main class="main"><header class="top"><div class="eyebrow">A JOURNEY THROUGH TIME</div><div class="brand"><span class="seal">迹</span>寻迹历史</div><div class="top-actions"><form id="top-search"><input name="q" placeholder="⌕  搜索人物、事件、地点" aria-label="搜索人物、事件、地点"></form><button aria-label="消息" data-action="messages">♧</button><button data-go="me" class="avatar" aria-label="个人中心">迹</button></div></header>${content}</main></div><nav class="bottom" aria-label="主导航">${navs.map(([id,icon,t])=>`<button data-go="${id}" class="${active===id?'active':''}"><i>${icon}</i>${t}</button>`).join('')}</nav>`;$('#top-search').onsubmit=e=>{e.preventDefault();go('search',encodeURIComponent(new FormData(e.target).get('q')))};}
function head(title,extra=''){return `<div class="pagehead"><div><div class="eyebrow">TRACES / ${new Date().getFullYear()}</div><h1>${title}</h1></div>${extra}</div>`}function back(){return '<button data-action="back" class="textbtn">← 返回上一页</button>'}
function home(){return `<section class="hero"><img src="${art(1)}" alt="青黛古塔主题插画"><div class="copy"><div class="eyebrow">今日寻迹 · 东坡的精神地图</div><h1>山河有迹<br>与千年知己相逢</h1><p>从一首词、一处古迹开始，<br>循着历史的线索，抵达真实的远方。</p>${button('沿着东坡的足迹  ↗','person','su','')}</div><span class="serial">VOL. 001 / 宋韵</span></section><section class="section"><div class="section-head"><h2>在历史中，找到你的好奇<span>EXPLORE THE ERAS</span></h2><small>朝代索引</small></div><div class="chips">${['全部','先秦','汉','唐','宋','明清'].map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="grid">${people.filter(p=>filter==='全部'||p.dynasty===filter).map(p=>card(p,'person')).join('')||'<div class="empty">该朝代档案正在整理，试试「唐」或「宋」。</div>'}</div></section><section class="section split"><div><div class="section-head"><h2>纸上春秋<span>READ THE SOURCES</span></h2>${button('更多考据 ↗','community','','textbtn')}</div><div class="quote"><div class="eyebrow">一日一读 · 史料摘选</div><p>“莫听穿林打叶声，<br>何妨吟啸且徐行。”</p><small>苏轼《定风波》· 宋 · 文学作品</small>${button('走进这段历史 →','event','rain','textbtn')}</div></div><div><div class="section-head"><h2>循迹而往<span>ON THE ROAD</span></h2>${button('全部路线 ↗','routes','','textbtn')}</div>${places.slice(0,2).map((p,i)=>`<button class="listitem" data-go="place" data-id="${p.id}"><span class="number">0${i+1}</span><div><h3>${p.name}</h3><small>${p.kind} · ${p.dynasty}</small></div><span>↗</span></button>`).join('')}<small>地点为精选推荐，尚未获取你的定位。</small></div></section><section class="section"><div class="section-head"><h2>同好之间<span>STORIES & VOICES</span></h2>${button('走进社区 ↗','community','','textbtn')}</div><div class="grid">${seeds.map(noteCard).join('')}</div></section><p class="notice">插画素材来自你提供的参考图，用作氛围展示，不代表遗址实拍。历史内容为精简演示档案。</p>`}
function person(id){let p=people.find(x=>x.id===id);if(!p)return missing();return `<div class="detail">${back()}<img class="banner" src="${art(p.img)}" alt="人物专题建筑插画">${tag(p.dynasty+'代人物')}<h1>${p.name}</h1><p class="muted">${p.desc}</p><div class="toolbar">${button('生平时间线','person',id,'textbtn')}${button('关联地点','place',id==='su'?'red':'tower','textbtn')}${button('社区笔记','community','','textbtn')}</div><h2>一生行旅</h2><div class="timeline">${(id==='su'?['1037 · 生于眉州眉山','1057 · 进士及第','1080 · 谪居黄州','1082 · 作《定风波》与赤壁二赋','1089 · 出知杭州，后疏浚西湖']:id==='li'?['701 · 李白生年（通行说）','742 · 奉诏入长安','744 · 离开长安','762 · 卒于当涂']:['1140 · 生于历城','1162 · 南归','1181 · 退居带湖','1207 · 卒于铅山']).map(t=>`<p>${t}</p>`).join('')}</div><h2>关联事件与地点</h2>${button(id==='su'?'沙湖道中遇雨 · 1082':'诗人与时代','event',id==='su'?'rain':'poetry')}${button('查看关联地点 →','place',id==='su'?'red':'tower')}<div class="source">史料索引：${id==='su'?'《宋史》卷三三八·苏轼传；苏轼《定风波》小序':id==='li'?'《旧唐书》卷一九〇下·李白传':'《宋史》卷四〇一·辛弃疾传'}。此页为演示摘要，精确日期及争议需进一步核对。</div></div>`}
function eventPage(id){if(!['rain','poetry'].includes(id))return missing();return `<div class="detail">${back()}${tag('文本可考')}<h1>${id==='rain'?'沙湖道中遇雨':'诗人与时代'}</h1><p class="muted">${id==='rain'?'1082 年 · 北宋 · 黄州':'唐宋文学 · 主题档案'}</p><p class="prose">${id==='rain'?'据《定风波》小序，三月七日沙湖道中遇雨，雨具先去，同行皆狼狈，而苏轼自述不觉，后来天晴，因而作词。\n\n这段记载提供了作品的创作情境。词中的达观可以作为文学解读，但不应进一步编造人物对话或具体行走路线。':'诗歌连接个体经验与时代环境。本专题以作品原文和传记材料为入口，区分传记事实、文学表达与后世阐释。'}</p><div class="source">史料原文（节选）：三月七日，沙湖道中遇雨。<br>出处：苏轼《定风波·莫听穿林打叶声》小序<br>不同层次：作品小序为文本记载；具体古道位置仍需考据。</div><h2>继续探索</h2><div class="row">${button('苏轼 · 人物档案','person','su')}${button('黄州东坡赤壁 · 纪念地','place','red')}</div></div>`}
function routes(){return `${head('把历史，走成一条路')}<div class="hero" style="min-height:250px"><img src="${art(2)}" alt="城门主题插画"><div class="copy"><div class="eyebrow">CURATED JOURNEY / 01</div><h1 style="font-size:34px">东坡的人生旷野</h1><p>黄州与杭州 · 两座城市，两段人生</p>${button('查看路线 →','route','dongpo','')}</div></div><div class="section-head section"><h2>精选寻迹路线</h2><small>行前请核对开放信息</small></div><div class="grid">${[{id:'dongpo',name:'循着东坡，走过风雨',dynasty:'宋',desc:'2 处地点 · 跨城主题路线 · 时间需自行规划',img:2},{id:'tang',name:'长安旧梦 · 古塔寻访',dynasty:'唐',desc:'1 处地点 · 建筑主题 · 建议半日',img:1}].map(p=>card(p,'route')).join('')}</div>`}
function route(id){if(!['dongpo','tang'].includes(id))return missing();let ps=id==='dongpo'?places.slice(0,2):places.slice(2);return `<div class="detail">${back()}${head(id==='dongpo'?'循着东坡，走过风雨':'长安旧梦 · 古塔寻访')}<p class="muted">${id==='dongpo'?'宋 · 苏轼 · 两地文学主题路线':'唐 · 古塔建筑主题'} · 史料摘要已标明出处</p><div class="route-map"><div class="row">${ps.map((p,i)=>`<b>${i+1} · ${p.name}</b>`).join('<span>⋯⋯→</span>')}</div></div><p class="notice">这是主题节点示意，不是实时导航。跨城交通、门票、开放时间与安全情况需出行前自行核实。</p>${ps.map(p=>`<button class="listitem" data-go="place" data-id="${p.id}"><div><h3>${p.name}</h3><small>${p.kind} · 查看历史背景与打卡入口</small></div>→</button>`).join('')}</div>`}
function place(id){let p=places.find(x=>x.id===id);if(!p)return missing();return `<div class="detail">${back()}<img class="banner" src="${art(p.img)}" alt="主题插画，非实景照片">${tag(p.kind)}${tag(p.dynasty)}<h1>${p.name}</h1><p class="prose">${p.desc}</p><div class="row">${button('开启 AR 留影 ◎','ar',p.id,'primary')}<button class="secondary" data-action="checkin" data-id="${p.id}">手动记录到访</button></div><div class="notice">当前未获取定位。到访记录由你手动确认，未经 GPS 验证。</div><h2>历史与此地的联系</h2><p class="prose">${p.id==='red'?'苏轼的赤壁书写为此地赋予了深厚的文学记忆。请区分文学中的赤壁与三国战场，二者不应直接等同。':'现存景观呈现多个时代的积累。历史背景、后世修复与当代景观应分别理解。'}</p><div class="row">${button(p.id==='tower'?'李白与盛唐':'苏轼 · 人物档案','person',p.id==='tower'?'li':'su')}${button('关联事件','event',p.id==='tower'?'poetry':'rain')}</div><div class="source">史料索引：${p.id==='tower'?'《大唐大慈恩寺三藏法师传》相关记述':'《宋史》苏轼传；苏轼《赤壁赋》及《后赤壁赋》'}。图片：用户提供的主题插画，非遗址实拍。</div><h2>我的到访记录</h2>${db.checkins.filter(c=>c.placeId===id).map(c=>`<p class="comment">${esc(c.date)} · 手动记录 · 未验证位置</p>`).join('')||'<div class="empty">还没有记录。到访后可以留下你的足迹。</div>'}</div>`}
function community(){return `${head('以史相会，以文结友',button('＋ 写笔记','edit','','primary'))}<p class="muted">让好奇有回应，让热爱有来处。</p><div class="chips">${['推荐','关注','人物考据','历史同人','遗址探访','文献解读','历史摄影'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="grid">${notes().filter(n=>n.visibility!=='private'&&(category==='推荐'||(category==='关注'?db.following&&n.author==='山河故人':n.category===category))).map(noteCard).join('')||'<div class="empty">这里暂时没有笔记。可以切换分类，或开始自己的创作。</div>'}</div>`}
function note(id){let n=findNote(id);if(!n)return missing();let own=db.notes.some(x=>x.id===id);return `<article class="detail">${back()}<div class="row">${tag(n.category)}${tag(n.category==='历史同人'?'文学虚构':'社区观点 · 请核对来源')}</div><h1>${esc(n.title)}</h1><div class="meta"><span>◯ ${esc(n.author)} · ${n.date||'精选演示内容'}</span>${own?button('编辑笔记','edit',id,'textbtn'):`<button data-action="follow">${db.following?'已关注':'＋ 关注作者'}</button>`}</div>${n.images?.length?n.images.map(src=>`<img class="banner" src="${esc(src)}" alt="笔记图片">`).join(''):`<img class="banner" src="${art(n.img||0)}" alt="笔记主题插画">`}<div class="prose">${esc(n.content)}</div><p>${tag(n.tags||'历史探索')}</p><div class="source">史料与创作说明<br>${esc(n.sources||'作者未提供来源，请谨慎核对。')}</div><div class="row">${button('关联人物 · 苏轼','person','su')}${button('关联地点 · 黄州','place','red')}</div><div class="toolbar"><button class="${db.likes.includes(id)?'on':''}" data-action="like" data-id="${id}">${db.likes.includes(id)?'♥':'♡'} 喜欢 ${db.likes.includes(id)?1:0}</button><button class="${db.favorites.includes(id)?'on':''}" data-action="favorite" data-id="${id}">${db.favorites.includes(id)?'★':'☆'} 收藏</button><button data-action="share">↗ 分享</button>${own?`<button data-action="delete" data-id="${id}" class="error">删除</button>`:''}</div><h2>在此交流 <small>${(db.comments[id]||[]).length}</small></h2><form id="comment-form"><label for="comment">写下你的想法</label><input id="comment" name="comment" required maxlength="500" placeholder="友善交流，分享你的发现"><button class="primary" style="margin-top:12px">发表本地评论</button></form>${(db.comments[id]||[]).map(c=>`<div class="comment"><small>我 · ${esc(c.date)}</small><p>${esc(c.text)}</p></div>`).join('')||'<p class="notice">还没有评论，留下第一条想法吧。</p>'}<section class="section"><h2>继续阅读</h2>${notes().filter(x=>x.id!==id).slice(0,2).map(x=>`<button class="listitem" data-go="note" data-id="${x.id}">${esc(x.title)} →</button>`).join('')}</section></article>`}
function editor(id){let n=id?findNote(id):db.draft||{};if(id&&!db.notes.some(x=>x.id===id))return missing();editorImages=n.images||[];return `<div class="detail">${back()}${head(id?'编辑你的笔记':'让历史，留下回声')}<div class="notice">笔记仅保存在当前浏览器；「公开」为原型展示状态，不会上传至社区服务器。</div><form id="editor" data-id="${id||''}"><label for="title">标题 *</label><input id="title" name="title" maxlength="60" required value="${esc(n.title||'')}" placeholder="给这段故事一个名字"><label for="content">正文 *（至少 20 字）</label><textarea id="content" name="content" required minlength="20" placeholder="写下你的考据、探访，或创作。区分史实与想象。">${esc(n.content||'')}</textarea><label for="category">内容分类</label><select id="category" name="category">${['人物考据','历史同人','遗址探访','文献解读','历史摄影'].map(c=>`<option ${n.category===c?'selected':''}>${c}</option>`).join('')}</select><label for="tags">朝代 / 人物 / 事件 / 地点标签</label><input id="tags" name="tags" value="${esc(n.tags||'')}" placeholder="例如：宋 · 苏轼 · 黄州"><label for="sources">史料来源与创作说明</label><textarea style="min-height:90px" id="sources" name="sources" placeholder="书名、卷次；同人创作请明确注明虚构">${esc(n.sources||'')}</textarea><label for="images">添加图片（最多 4 张，每张 2MB 以内）</label><input type="file" id="images" accept="image/*" multiple><div id="photos" class="photo-list"></div><label for="visibility">可见范围</label><select id="visibility" name="visibility"><option value="public">公开（本地演示）</option><option value="private" ${n.visibility==='private'?'selected':''}>仅自己可见</option></select><div id="validation" class="error" role="alert"></div><div class="row section"><button type="button" class="secondary" data-action="draft">保存草稿</button><button type="button" class="secondary" data-action="preview">预览</button><button class="primary">${id?'保存修改':'发布至本地'}</button></div><div id="preview-box"></div></form></div>`}
function search(q=''){q=decodeURIComponent(q);let data=[...people.map(x=>({...x,type:'人物',route:'person'})),...places.map(x=>({...x,type:'地点',route:'place'})),{id:'rain',name:'沙湖道中遇雨',desc:'苏轼 · 宋 · 定风波',type:'事件',route:'event'},...notes().map(x=>({...x,name:x.title,desc:x.author+' '+x.tags+' '+x.category,type:'笔记',route:'note'}))];let results=data.filter(x=>(searchType==='全部'||x.type===searchType)&&(!q||(x.name+x.desc+x.dynasty).includes(q)));return `${head('每一个名字，都是入口')}<form id="search-form" class="row"><input name="q" value="${esc(q)}" aria-label="搜索关键词" placeholder="试试「苏轼」「宋」「黄州」" style="flex:1"><button class="primary">搜索</button><button type="button" class="secondary" data-go="search">清空</button></form><div class="chips">${['全部','人物','事件','地点','笔记'].map(t=>`<button class="chip ${searchType===t?'active':''}" data-searchtype="${t}">${t}</button>`).join('')}</div>${!q?'<p class="notice">热门线索：苏轼 · 西湖 · 李白。支持人物、事件、地点、笔记标题、作者及标签搜索。</p>':''}${!q&&db.recentSearches?.length?'<div class="row"><small>最近搜索</small>'+db.recentSearches.map(t=>button(esc(t),'search',encodeURIComponent(t),'chip')).join('')+'</div>':''}<div class="search-results">${results.map(x=>`<button class="listitem" data-go="${x.route}" data-id="${x.id}"><div>${tag(x.type)}<h3>${esc(x.name)}</h3><small>${esc(x.desc)}</small></div>→</button>`).join('')||`<div class="empty"><h2>还没有找到这条线索</h2><p>试试更短的关键词，如「苏轼」或「西湖」。</p>${button('重新浏览全部','search')}</div>`}</div>`}
const badgeData=()=>[{name:'初踏山河',type:'探索',symbol:'♧',value:db.checkins.length,target:1,task:'记录一次手动到访',route:'routes'},{name:'案头寻真',type:'考据',symbol:'▥',value:db.favorites.length,target:2,task:'收藏 2 篇笔记',route:'community'},{name:'落笔成章',type:'创作',symbol:'✎',value:db.notes.length,target:1,task:'发布第一篇本地笔记',route:'edit'},{name:'以文会友',type:'社区',symbol:'❀',value:Object.values(db.comments).flat().length,target:3,task:'发表 3 条评论',route:'community'}];
function badges(){return `${head('每一份热爱，都有回响')}<p class="muted">探索 · 考据 · 创作 · 社区</p><div class="badges section">${badgeData().map((b,i)=>`<div class="badge ${b.value>=b.target?'unlocked':''}"><div class="medal">${b.symbol}</div><small>${b.type}</small><h3>${b.name}</h3><p>${b.task}</p><progress value="${b.value}" max="${b.target}"></progress><p class="muted">${Math.min(b.value,b.target)} / ${b.target} · ${b.value>=b.target?'已获得':'待解锁'}</p>${b.value>=b.target?`<small>获得于 ${esc(db.badgeDates?.[i]||'本次本地操作')}</small>`:button('去完成 →',b.route,'','textbtn')}</div>`).join('')}</div><p class="notice">勋章仅根据本浏览器的实际操作解锁。手动打卡未经位置验证。</p>`}
function me(){return `${head('我的历史行囊')}<div class="profile"><span class="avatar">迹</span><div><h2>山河寻迹人</h2><p class="muted">在字里行间，也在山河之间。</p><small>本地访客 · 无需登录</small></div></div><div class="stat"><div><strong>${db.checkins.length}</strong>探索足迹</div><div><strong>${db.notes.length}</strong>我的创作</div><div><strong>${badgeData().filter(b=>b.value>=b.target).length}</strong>获得勋章</div></div>${button('查看我的勋章墙 →','badges','','primary')}<div class="section-head section"><h2>我的创作</h2>${button('＋ 写笔记','edit','','textbtn')}</div>${db.draft?button('继续编辑草稿 →','edit','','secondary'):''}${db.notes.map(n=>`<button class="listitem" data-go="note" data-id="${n.id}">${esc(n.title)} ${tag(n.visibility==='private'?'仅自己':'本地公开')} →</button>`).join('')||'<p class="notice">还没有发布笔记。第一段故事，等你落笔。</p>'}<h2 class="section">收藏夹</h2>${db.favorites.map(id=>findNote(id)).filter(Boolean).map(n=>`<button class="listitem" data-go="note" data-id="${n.id}">${esc(n.title)} →</button>`).join('')||'<p class="notice">收藏你感兴趣的笔记，在这里重逢。</p>'}<h2 class="section">探索足迹</h2>${db.checkins.map(c=>`<button class="listitem" data-go="place" data-id="${c.placeId}"><div>${places.find(p=>p.id===c.placeId)?.name}<br><small>${esc(c.date)} · 手动记录，未验证位置</small></div>→</button>`).join('')||'<p class="notice">暂时没有到访记录。</p>'}<h2 class="section">最近浏览</h2>${db.visited.slice(-5).reverse().map(v=>`<button class="listitem" data-go="${v.type}" data-id="${v.id}">${esc(v.name)} →</button>`).join('')||'<p class="notice">从发现页开始你的旅程。</p>'}<h2 class="section">设置与隐私</h2><p class="notice">所有操作数据仅保存在当前浏览器 LocalStorage。清理浏览器数据会丢失笔记、图片与记录。未提供云端同步、账号登录或真实社区服务。</p><button class="secondary" data-action="export">导出我的本地数据</button> <button class="secondary error" data-action="reset">清除本地数据</button> ${button('查看错误重试示例','error','','textbtn')}`}
function ar(id='red'){let p=places.find(x=>x.id===id)||places[0];return `<div class="detail">${head('留下一枚，属于此刻的印记')}<div class="notice">2D 相机叠印演示。没有三维识别、GPS 核验或云端上传。相机只在你点击授权后开启。</div><label for="place-select">关联地点</label><select id="place-select">${places.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name}</option>`).join('')}</select><div class="camera section">${photo?`<img src="${photo}" alt="已拍摄的合成照片">`:simulate?`<img id="simulation" src="${art(p.img)}" alt="模拟取景插画">`:'<video id="video" autoplay playsinline muted></video>'}${!photo?`<span class="hint">${simulate?'模拟取景 · 不是真实拍摄':stream?'相机已开启':'相机尚未开启'}</span><div class="stamp">${esc(stamp)}<small style="font-size:11px;color:inherit">${p.name} · ${new Date().toLocaleDateString('zh-CN')}</small></div>`:''}</div><div id="camera-error" class="error" role="alert"></div><div class="chips">${['寻迹留念','山河故人','与古为新'].map(s=>`<button class="chip ${stamp===s?'active':''}" data-stamp="${s}">${s}</button>`).join('')}</div><div class="row">${photo?'<button class="primary" data-action="download">保存照片</button><button class="secondary" data-action="retake">重新拍摄</button><button class="secondary" data-action="photo-note">用于写笔记</button>':'<button class="primary" data-action="camera">授权开启相机</button><button class="secondary" data-action="simulate">使用模拟模式</button><button class="primary" data-action="capture">◎ 拍摄</button>'}<button class="secondary" data-action="checkin" data-id="${p.id}">手动记录到访</button></div><p class="notice">模拟照片使用用户提供的插画。保存会下载到你的设备；本地打卡需另行确认。</p></div>`}
function missing(){return `<div class="empty"><div class="eyebrow">404 / LOST IN TIME</div><h1>这条线索暂时不在这里</h1><p>内容可能已删除，回到发现页继续探索。</p>${button('回到发现','home','','primary')}</div>`}
function errorPage(){return `<div class="empty"><h1>暂时未能载入这段历史</h1><p>这是错误状态演示，点击重试将重新读取本地档案。</p>${button('重试读取','home','','primary')}</div>`}
function updateBadges(){db.badgeDates||={};badgeData().forEach((b,i)=>{if(b.value>=b.target&&!db.badgeDates[i])db.badgeDates[i]=new Date().toLocaleDateString('zh-CN')});save()}
function render(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}let [p='home',id='']=location.hash.slice(2).split('/');if(!p)p='home';let content;try{content=({home,person:()=>person(id),event:()=>eventPage(id),routes,route:()=>route(id),place:()=>place(id),community,note:()=>note(id),edit:()=>editor(id),search:()=>search(id),badges,me,ar:()=>ar(id),error:errorPage}[p]||missing)()}catch(e){console.error(e);content=errorPage()}shell(content,p);window.scrollTo(0,0);if(['person','place','note','event'].includes(p)){let name=p==='person'?people.find(x=>x.id===id)?.name:p==='place'?places.find(x=>x.id===id)?.name:p==='note'?findNote(id)?.title:'沙湖道中遇雨';if(name){db.visited=db.visited.filter(v=>v.id!==id);db.visited.push({type:p,id,name});save()}}if(p==='note'&&$('#comment-form'))$('#comment-form').onsubmit=e=>{e.preventDefault();let t=new FormData(e.target).get('comment').trim();if(!t)return;db.comments[id]||=[];db.comments[id].push({text:t,date:new Date().toLocaleDateString('zh-CN')});updateBadges();render();toast('评论已保存在本地')};if(p==='search')$('#search-form').onsubmit=e=>{e.preventDefault();go('search',encodeURIComponent(new FormData(e.target).get('q')))};if(p==='edit'){renderPhotos();$('#editor').onsubmit=publish;$('#images').onchange=async e=>{for(const f of e.target.files){if(editorImages.length>=4||f.size>2*1024*1024){toast('最多 4 张图片，每张不超过 2MB');break}if(!f.type.startsWith('image/'))continue;editorImages.push(await new Promise(res=>{let r=new FileReader;r.onload=()=>res(r.result);r.readAsDataURL(f)}))}renderPhotos()}}if(p==='ar')$('#place-select').onchange=e=>{photo='';go('ar',e.target.value)}}
function renderPhotos(){if(!$('#photos'))return;$('#photos').innerHTML=editorImages.map((src,i)=>`<div><img src="${esc(src)}" alt="已选图片 ${i+1}"><div><button type="button" data-photo="up" data-index="${i}">前移</button><button type="button" data-photo="remove" data-index="${i}">移除</button></div></div>`).join('')}
function formData(){return {...Object.fromEntries(new FormData($('#editor'))),images:[...editorImages]}}
function publish(e){e.preventDefault();let n=formData();if(!n.title.trim()||n.content.trim().length<20){$('#validation').textContent='请填写标题，并输入至少 20 字正文。';return}let id=e.target.dataset.id||'local-'+Date.now();n={...n,id,author:'我',date:new Date().toLocaleDateString('zh-CN'),img:0};let old=[...db.notes];db.notes=db.notes.filter(x=>x.id!==id);db.notes.unshift(n);if(!save()){db.notes=old;$('#validation').textContent='保存失败，内容已保留在编辑器中，请减少图片后重试。';return}db.draft=null;updateBadges();go('note',id);toast('笔记已保存在当前浏览器')}
async function camera(){if(!navigator.mediaDevices?.getUserMedia){$('#camera-error').textContent='当前环境不支持相机。请使用安全连接或模拟模式。';return}try{stream?.getTracks().forEach(t=>t.stop());stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});simulate=false;photo='';let c=$('.camera');c.innerHTML='<video id="video" autoplay playsinline muted></video><span class="hint">相机已开启 · 2D 印记叠加</span><div class="stamp">'+esc(stamp)+'</div>';$('#video').srcObject=stream;await $('#video').play();$('#camera-error').textContent=''}catch(e){$('#camera-error').textContent='相机未能开启：可能未授权、被占用或设备不可用。可重试授权，或选择模拟模式。'}}
function capture(){let src=simulate?$('#simulation'):$('#video');if(!src||(simulate?!src.complete:!src.videoWidth)){toast('请先开启相机或使用模拟模式');return}let c=document.createElement('canvas');c.width=900;c.height=1200;let x=c.getContext('2d');let w=src.videoWidth||src.naturalWidth,h=src.videoHeight||src.naturalHeight,scale=Math.max(c.width/w,c.height/h);x.drawImage(src,(c.width-w*scale)/2,(c.height-h*scale)/2,w*scale,h*scale);x.strokeStyle='#f1ddba';x.lineWidth=8;x.strokeRect(30,30,840,1140);x.fillStyle='#faf0d6';x.font='42px serif';x.fillText(stamp,70,1040);x.font='23px sans-serif';x.fillText((places.find(p=>p.id===$('#place-select').value)?.name||'寻迹')+' · '+new Date().toLocaleDateString('zh-CN'),70,1095);if(simulate){x.font='20px sans-serif';x.fillText('模拟取景 · 参考插画',70,80)}photo=c.toDataURL('image/jpeg',.85);render();toast('照片已生成，可保存或写笔记')}
function download(data,name){let a=document.createElement('a');a.href=data;a.download=name;a.click()}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go){go(b.dataset.go,b.dataset.id||'');return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.category){category=b.dataset.category;render();return}if(b.dataset.searchtype){searchType=b.dataset.searchtype;render();return}if(b.dataset.stamp){stamp=b.dataset.stamp;if(!stream)render();else $('.stamp').textContent=stamp;return}if(b.dataset.photo){let i=+b.dataset.index;if(b.dataset.photo==='remove')editorImages.splice(i,1);else if(i>0)[editorImages[i-1],editorImages[i]]=[editorImages[i],editorImages[i-1]];renderPhotos();return}let a=b.dataset.action,id=b.dataset.id;switch(a){case'back':if(history.length>1)history.back();else go('home');break;case'messages':toast('暂无消息；当前为本地访客模式');break;case'like':case'favorite':{let prop=a==='like'?'likes':'favorites';db[prop]=db[prop].includes(id)?db[prop].filter(x=>x!==id):[...db[prop],id];updateBadges();render();break}case'follow':db.following=!db.following;save();render();break;case'share':try{await navigator.clipboard.writeText(location.href);toast('已复制页面链接；本地笔记不会随链接同步')}catch{toast('无法访问剪贴板，请复制浏览器地址')}break;case'delete':if(confirm('确定删除这篇本地笔记？此操作无法撤销。')){db.notes=db.notes.filter(n=>n.id!==id);db.favorites=db.favorites.filter(x=>x!==id);save();go('me')}break;case'draft':db.draft=formData();if(save())toast('草稿已保存');break;case'preview':{let n=formData();$('#preview-box').innerHTML=`<div class="source"><h2>${esc(n.title||'未命名笔记')}</h2>${tag(n.category)}<p class="prose">${esc(n.content)}</p><p>${esc(n.sources)}</p></div>`;$('#preview-box').scrollIntoView({behavior:'smooth'});break}case'camera':await camera();break;case'simulate':simulate=true;photo='';render();break;case'capture':capture();break;case'retake':photo='';render();break;case'download':if(photo)download(photo,'寻迹留影-'+Date.now()+'.jpg');break;case'photo-note':db.draft={title:'我的寻迹留影',content:'',images:[photo],category:'遗址探访',tags:$('#place-select').selectedOptions[0].text};save();go('edit');break;case'checkin':if(confirm('确认记录到访？这是手动记录，不会核验 GPS 位置。')){db.checkins.push({id:Date.now(),placeId:id,date:new Date().toLocaleString('zh-CN'),verificationStatus:'unverified'});updateBadges();toast('已保存手动到访记录')}break;case'export':download('data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(db,null,2)),'寻迹历史-本地数据.json');break;case'reset':if(confirm('清除当前浏览器全部笔记、草稿、收藏与足迹？建议先导出数据。')){localStorage.removeItem(key);location.reload()}break}});
window.addEventListener('hashchange',render);window.addEventListener('offline',render);window.addEventListener('online',render);window.addEventListener('pagehide',()=>stream?.getTracks().forEach(t=>t.stop()));render();

document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){e.target.alt='图片未能载入 · 可继续阅读文字内容';e.target.style.background='var(--wash)'}},true);
